function draw({svg,width,height,progress,params}) {

  const NS='http://www.w3.org/2000/svg';
  const palette={ink:'#243b48',muted:'#667984',grid:'#e1e8e8',blue:'#166a75',orange:'#bd6136',light:'#edf5f3'};
  svg.setAttribute('viewBox',`0 0 ${width} ${height}`);
  svg.setAttribute('role','img');
  const nodes=svg.__directNodes||(svg.__directNodes=new Map());
  const used=new Set();
  function el(key,tag,attrs={},value){
    used.add(key);let n=nodes.get(key);
    if(!n){n=document.createElementNS(NS,tag);svg.appendChild(n);nodes.set(key,n);}
    for(const [a,v] of Object.entries(attrs))n.setAttribute(a,String(v));
    if(value!==undefined)n.textContent=value;
    return n;
  }
  function text(key,x,y,value,attrs={}){return el(key,'text',{x,y,fill:palette.ink,'font-size':12,'font-family':'system-ui, sans-serif',...attrs},value);}
  function line(key,x1,y1,x2,y2,attrs={}){return el(key,'line',{x1,y1,x2,y2,stroke:palette.grid,'stroke-width':1,...attrs});}
  function path(key,d,attrs={}){return el(key,'path',{d,fill:'none',stroke:palette.blue,'stroke-width':2,...attrs});}
  function dot(key,x,y,r=4,attrs={}){return el(key,'circle',{cx:x,cy:y,r,fill:palette.blue,...attrs});}
  function panel(key,box,xd,yd,xticks,yticks,xname,yname){
    const [l,t,w,h]=box;
    const X=v=>l+(v-xd[0])/(xd[1]-xd[0])*w;
    const Y=v=>t+h-(v-yd[0])/(yd[1]-yd[0])*h;
    for(const v of yticks){line(key+'gy'+v,l,Y(v),l+w,Y(v));text(key+'yt'+v,l-8,Y(v)+4,v,{'text-anchor':'end',fill:palette.muted});}
    for(const v of xticks){line(key+'gx'+v,X(v),t,X(v),t+h,{stroke:palette.grid,'stroke-opacity':0.55});text(key+'xt'+v,X(v),t+h+19,v,{'text-anchor':'middle',fill:palette.muted});}
    line(key+'ya',l,t,l,t+h,{stroke:palette.muted});line(key+'xa',l,t+h,l+w,t+h,{stroke:palette.muted});
    text(key+'yl',l,t-14,yname,{'font-size':12});
    text(key+'xl',l+w,t+h+39,xname,{'text-anchor':'end'});
    return {X,Y,l,t,w,h};
  }
  function curve(key,P,x0,x1,f,attrs={}){let d='';for(let i=0;i<=120;i++){const x=x0+(x1-x0)*i/120;d+=(i?'L':'M')+P.X(x).toFixed(3)+','+P.Y(f(x)).toFixed(3);}path(key,d,attrs);}
  function end(){for(const [key,n] of nodes){if(!used.has(key)){n.remove();nodes.delete(key);}}}
  const mobile=width<600;
  const fmt=v=>(Math.abs(v)<0.0005?0:v).toFixed(3);

  el('title','title',{},'同一小批量的残差、参数移动与损失；展开一次负梯度更新');
  const eta=Number(params.eta),p=Math.max(0,Math.min(1,progress));
  const data=[[-1,-1],[0,0.5],[1,2]];
  const start={w:0.5,b:-0.5};
  const initialResiduals=data.map(([x,y])=>start.w*x+start.b-y);
  const gw=data.reduce((s,[x],i)=>s+x*initialResiduals[i],0)/3;
  const gb=initialResiduals.reduce((s,r)=>s+r,0)/3;
  const target={w:start.w-eta*gw,b:start.b-eta*gb};
  const w=start.w+p*(target.w-start.w),b=start.b+p*(target.b-start.b);
  const residuals=data.map(([x,y])=>w*x+b-y);
  const loss=residuals.reduce((s,r)=>s+r*r/2,0)/3;
  const lossAt=(a,c)=>(a-1.5)**2/3+(c-0.5)**2/2;
  const yTop=mobile?62:64;
  let A,B;
  if(mobile){
    const ph=(height-202)/2;
    A=panel('fit',[38,52,width-55,ph],[-1.2,1.2],[-2,4.5],[-1,0,1],[-2,0,2,4],'特征 x','标签 / 预测 y');
    B=panel('param',[38,ph+133,width-55,ph],[-0.1,2.3],[-0.7,2.1],[0,1,2],[0,1,2],'权重 w','偏置 b');
  }else{
    const pw=(width-146)/2,ph=height-132;
    A=panel('fit',[44,yTop,pw,ph],[-1.2,1.2],[-2,4.5],[-1,0,1],[-2,0,2,4],'特征 x','标签 / 预测 y');
    B=panel('param',[pw+119,yTop,pw,ph],[-0.1,2.3],[-0.7,2.1],[0,1,2],[0,1,2],'权重 w','偏置 b');
  }
  text('status',A.l,19,`w ${fmt(w)}   b ${fmt(b)}   L ${fmt(loss)}`,{'font-size':13});
  text('gradient',B.l,mobile?B.t-31:19,`起点：平均 xr ${fmt(gw)}   平均 r ${fmt(gb)}`,{fill:palette.muted});
  text('old-label',A.l+A.w,A.t-14,'虚线：起点预测',{'text-anchor':'end',fill:palette.muted});
  curve('old-fit',A,-1.2,1.2,x=>start.w*x+start.b, {stroke:palette.muted,'stroke-width':1.4,'stroke-dasharray':'4 4'});
  curve('current-fit',A,-1.2,1.2,x=>w*x+b);
  data.forEach(([x,y],i)=>{
    line('res'+i,A.X(x),A.Y(y),A.X(x),A.Y(w*x+b),{stroke:palette.orange,'stroke-width':2.5});
    dot('pred'+i,A.X(x),A.Y(w*x+b),3,{fill:palette.light,stroke:palette.blue,'stroke-width':1.5});
    dot('obs'+i,A.X(x),A.Y(y),4,{fill:palette.ink});
  });
  // Ellipses are exact level sets of L=(w-1.5)^2/3+(b-0.5)^2/2.
  const levels=[0.05,0.2,0.5,0.9];
  levels.forEach((v,i)=>{
    let d='';let open=false;
    for(let k=0;k<=240;k++){
      const a=k/240*Math.PI*2,ww=1.5+Math.sqrt(3*v)*Math.cos(a),bb=0.5+Math.sqrt(2*v)*Math.sin(a);
      if(ww>=-0.1&&ww<=2.3&&bb>=-0.7&&bb<=2.1){d+=(open?'L':'M')+B.X(ww).toFixed(3)+','+B.Y(bb).toFixed(3);open=true;}else open=false;
    }
    path('contour'+i,d,{stroke:'#ccd9d9','stroke-width':1});
  });
  line('step',B.X(start.w),B.Y(start.b),B.X(target.w),B.Y(target.b),{stroke:palette.orange,'stroke-width':1.5,'stroke-dasharray':'4 4'});
  const tx=B.X(target.w),ty=B.Y(target.b),sx=B.X(start.w),sy=B.Y(start.b),ang=Math.atan2(ty-sy,tx-sx);
  path('arrow',`M ${tx-8*Math.cos(ang-0.45)},${ty-8*Math.sin(ang-0.45)} L ${tx},${ty} L ${tx-8*Math.cos(ang+0.45)},${ty-8*Math.sin(ang+0.45)}`,{stroke:palette.orange,'stroke-width':1.5});
  dot('start',sx,sy,4,{fill:palette.light,stroke:palette.orange,'stroke-width':1.5});
  dot('target',tx,ty,3,{fill:palette.orange});
  dot('current',B.X(w),B.Y(b),5,{fill:palette.blue,stroke:'#ffffff','stroke-width':1.5});
  // A small cross retains the minimizer when the moving dot reaches it.
  const ox=B.X(1.5),oy=B.Y(0.5);
  line('opt-h',ox-5,oy,ox+5,oy,{stroke:palette.ink,'stroke-width':1.6});
  line('opt-v',ox,oy-5,ox,oy+5,{stroke:palette.ink,'stroke-width':1.6});
  text('opt-label',ox+9,oy+16,'最小点',{fill:palette.muted});
  text('step-label',B.l+B.w,B.t-14,'虚线：−ηg',{'text-anchor':'end',fill:palette.orange});
  const legendY=height-9;
  if(mobile){
    text('legend',18,legendY,`● 观测   ○ 预测   橙线：残差 / 更新`,{'font-size':12});
  }else{
    text('legend',A.l,legendY,'● 观测   ○ 预测   橙线：残差',{fill:palette.muted});
    text('levels',B.l,legendY,'等高线：损失相同   × 最小点',{fill:palette.muted});
  }
  end();
  return {eta,progress:p,data,start,initialResiduals,initialGradient:[gw,gb],target,current:[w,b],predictions:data.map(([x])=>w*x+b),residuals,loss,startLoss:lossAt(start.w,start.b),targetLoss:lossAt(target.w,target.b),contourLevels:levels,minimizer:[1.5,0.5],minLoss:0};
}

