  function end(){for(const [key,n] of nodes){if(!used.has(key)){n.remove();nodes.delete(key);}}}
  const mobile=width<600;
  const fmt=v=>(Math.abs(v)<0.0005?0:v).toFixed(3);

  el('title','title',{},'三个固定观测的高斯密度和两种目标；改变偏置与固定噪声尺度');
  const b=Number(params.bias),sigma=Number(params.sigma),ys=[-1,0,1];
  const density=y=>Math.exp(-0.5*((y-b)/sigma)**2)/(Math.sqrt(2*Math.PI)*sigma);
  const L=a=>ys.reduce((s,y)=>s+(a-y)**2/2,0)/3;
  const C=Math.log(Math.sqrt(2*Math.PI)*sigma);
  const NLL=a=>C+L(a)/(sigma*sigma);
  let A,B;
  if(mobile){
    const ph=(height-214)/2;
    A=panel('pdf',[40,55,width-57,ph],[-4,4],[0,0.62],[-3,0,3],[0,0.3,0.6],'观测值 y','概率密度 p(y)');
    B=panel('cost',[40,ph+140,width-57,ph],[-2.1,2.1],[0,5.7],[-2,0,2],[0,2,4],'候选偏置 b','平均目标值');
  }else{
    const pw=(width-146)/2,ph=height-140;
    A=panel('pdf',[44,67,pw,ph],[-4,4],[0,0.62],[-3,0,3],[0,0.3,0.6],'观测值 y','概率密度 p(y)');
