  for(let i=0;i<=160;i++){const y=-4+8*i/160;area+=` L ${A.X(y)},${A.Y(density(y))}`;}
  area+=` L ${A.X(4)},${A.Y(0)} Z`;
  path('area',area,{fill:palette.light,stroke:'none'});
  curve('pdf',A,-4,4,density);
  ys.forEach((y,i)=>{
    line('stick'+i,A.X(y),A.Y(0),A.X(y),A.Y(density(y)),{stroke:palette.orange,'stroke-width':1.7});
    dot('pdf-dot'+i,A.X(y),A.Y(density(y)),3.5,{fill:palette.orange});
    path('rug'+i,`M ${A.X(y)-3},${A.Y(0)+3} L ${A.X(y)+3},${A.Y(0)+3}`,{stroke:palette.orange,'stroke-width':2.5});
  });
  curve('loss',B,-2,2,L);
  curve('nll',B,-2,2,NLL,{stroke:palette.orange});
  line('minimum',B.X(0),B.Y(0),B.X(0),B.Y(5.7),{stroke:palette.muted,'stroke-dasharray':'3 4','stroke-opacity':0.6});
  line('selection',B.X(b),B.Y(0),B.X(b),B.Y(Math.max(L(b),NLL(b))),{stroke:palette.muted,'stroke-width':1});
  dot('loss-dot',B.X(b),B.Y(L(b)),4.5,{fill:palette.blue});
  dot('nll-dot',B.X(b),B.Y(NLL(b)),4.5,{fill:palette.orange});
  text('min-label',B.X(0),B.t+13,'最小点 b = 0',{'text-anchor':'middle',fill:palette.muted,'font-size':12});
  text('observations',A.l+A.w,A.t-14,'橙点：固定观测',{'text-anchor':'end',fill:palette.orange,'font-size':12});
  const yy=height-9;
  const ll=mobile?19:B.l;
  line('loss-key',ll,yy-4,ll+14,yy-4,{stroke:palette.blue,'stroke-width':2});
  text('loss-label',ll+20,yy,'平方损失');
  line('nll-key',ll+91,yy-4,ll+105,yy-4,{stroke:palette.orange,'stroke-width':2});
  text('nll-label',ll+111,yy,'负对数似然 / n');
  if(!mobile)text('left-foot',A.l,yy,'每个橙点的高度是对应观测的密度',{fill:palette.muted});
  end();
  return {bias:b,sigma,observations:ys,densities:ys.map(density),residuals:ys.map(y=>b-y),meanHalfSquaredLoss:L(b),negativeLogLikelihood:3*NLL(b),meanNegativeLogLikelihood:NLL(b),constantPerSample:C,positiveScale:1/(sigma*sigma),minimizer:0,lossAtMin:L(0),nllAtMin:NLL(0)};
}
